/**
 * Unit tests for JacksonAnnotationIntrospector#findEnumValues
 */
public class JacksonAnnotationIntrospector_findEnumValues_TriageGen1Test {

    private JacksonAnnotationIntrospector introspector;

    @Before
    public void setUp() {
        introspector = new JacksonAnnotationIntrospector();
    }

    // Test Enums for various scenarios

    enum SimpleEnum {
        VALUE_ONE,
        VALUE_TWO
    }

    enum AnnotatedEnum {
        @JsonProperty("one")
        FIRST,
        @JsonProperty("two")
        SECOND,
        @JsonProperty("")
        EMPTY_PROP,
        THIRD // No annotation
    }

    enum MixedEnum {
        @JsonProperty("val_a")
        A,
        B, // No annotation
        @JsonProperty("val_c")
        C
    }

    @Test
    public void testFindEnumValues_NoAnnotations() {
        SimpleEnum[] values = SimpleEnum.values();
        String[] names = new String[values.length];

        String[] result = introspector.findEnumValues(SimpleEnum.class, values, names);

        // Since no JsonProperty annotations are present, names should remain null/unchanged
        for (int i = 0; i < values.length; i++) {
            assertEquals(null, result[i]);
        }
    }

    @Test
    public void testFindEnumValues_WithAnnotations() {
        AnnotatedEnum[] values = AnnotatedEnum.values();
        String[] names = new String[values.length];

        // Expected: 
        // FIRST -> "one"
        // SECOND -> "two"
        // EMPTY_PROP -> null (because prop.value().isEmpty() is checked)
        // THIRD -> null (no annotation)

        String[] result = introspector.findEnumValues(AnnotatedEnum.class, values, names);

        assertEquals("one", result[0]);
        assertEquals("two", result[1]);
        assertEquals(null, result[2]);
        assertEquals(null, result[3]);
    }

    @Test
    public void testFindEnumValues_Mixed() {
        MixedEnum[] values = MixedEnum.values();
        String[] names = new String[values.length];

        String[] result = introspector.findEnumValues(MixedEnum.class, values, names);

        assertEquals("val_a", result[0]);
        assertEquals(null, result[1]);
        assertEquals("val_c", result[2]);
    }

    @Test
    public void testFindEnumValues_EmptyInputs() {
        // Test with empty arrays
        String[] names = new String[0];
        Enum<?>[] values = new Enum<?>[0];
        String[] result = introspector.findEnumValues(SimpleEnum.class, values, names);
        assertEquals(0, result.length);
    }

    /**
     * This test covers the branch where expl is null (no valid JsonProperty annotations found)
     */
    @Test
    public void testFindEnumValues_NoValidPropertiesFound() {
        SimpleEnum[] values = SimpleEnum.values();
        String[] names = new String[values.length];
        // Fill names with something to ensure they aren't touched if expl is null
        for(int i=0; i<names.length; i++) names[i] = "original";

        String[] result = introspector.findEnumValues(SimpleEnum.class, values, names);

        assertArrayEquals(new String[]{"original", "original"}, result);
    }

    /**
     * Test scenario where the enum constant name is not in the map (expl.get(defName) == null)
     * This is covered by the MixedEnum test, but explicitly ensuring the logic path.
     */
    @Test
    public void testFindEnumValues_PartialMapping() {
        MixedEnum[] values = {MixedEnum.A, MixedEnum.B};
        String[] names = new String[2];

        String[] result = introspector.findEnumValues(MixedEnum.class, values, names);

        assertEquals("val_a", result[0]);
        assertEquals(null, result[1]);
    }
}
